"use client";
import "./styles/skeuo-slider.css";

import type { InputHTMLAttributes } from "react";
export type SkeuoSliderProps = Omit<InputHTMLAttributes<HTMLInputElement>, "type" | "value" | "onChange"> & {
  value: number;
  onValueChange: (value: number) => void;
};
export function SkeuoSlider({ value, onValueChange, min = 0, max = 100, className = "", ...props }: SkeuoSliderProps) {
  const progress = Math.min(100, Math.max(0, (value - Number(min)) / (Number(max) - Number(min) || 1) * 100));
  return <div data-sk-root="" className={`sk-slider-housing ${className}`} data-disabled={props.disabled || undefined}><span className="sk-slider-track" aria-hidden="true"><i style={{ width: `${progress}%` }} /></span><input {...props} type="range" min={min} max={max} value={value} onChange={e => onValueChange(Number(e.target.value))} /><div className="sk-slider-ticks" aria-hidden="true">{Array.from({ length: 21 }, (_, i) => <i key={i} />)}</div></div>;
}

@import "./skeuo-base.css";
.sk-slider-housing input[type="range"]{ -webkit-appearance: none; appearance: none; width: 100%; height: 7px; border: 1px solid var(--sk-edge); border-radius: 8px; background: linear-gradient(to right,var(--sk-accent) var(--sk-range,50%),var(--sk-well) var(--sk-range,50%)); box-shadow: inset 0 1px 2px var(--sk-shadow); cursor: pointer; }
.sk-slider-housing input[type="range"]::-webkit-slider-thumb{ -webkit-appearance: none; width: 19px; height: 24px; border: 1px solid var(--sk-key-edge); border-radius: 5px; background: linear-gradient(var(--sk-surface-raised),var(--sk-surface)); box-shadow: inset 0 2px 0 var(--sk-highlight),0 2px 2px var(--sk-shadow); }
.sk-slider-housing input[type="range"]::-moz-range-thumb{ width: 19px; height: 24px; border: 1px solid var(--sk-key-edge); border-radius: 5px; background: var(--sk-surface-raised); }
.sk-slider-housing{ position: relative; padding: 0 15px; height: 57px; border: 1px solid var(--sk-edge); border-radius: 9px; background: linear-gradient(160deg,var(--sk-surface-raised),var(--sk-surface)); box-shadow: inset 0 1px 0 var(--sk-highlight),0 2px 0 var(--sk-base),0 3px 0 var(--sk-edge); }
.sk-slider-track{ position: absolute; top: 20px; left: 16px; right: 16px; height: 7px; border-radius: 5px; overflow: hidden; border: 1px solid var(--sk-edge); background: var(--sk-well); box-shadow: inset 0 2px 3px var(--sk-shadow),0 1px 0 var(--sk-highlight); }
.sk-slider-track i{ display: block; height: 100%; background: var(--sk-accent); box-shadow: inset 0 2px 3px #00000030; }
.sk-slider-housing input[type="range"]{ position: relative; z-index: 1; width: 100%; height: 44px; margin: 0; border: 0; background: none; box-shadow: none; }
.sk-slider-housing input[type="range"]::-webkit-slider-thumb{ width: 26px; height: 34px; border-radius: 6px; border: 1px solid var(--sk-key-edge); background: linear-gradient(to bottom,transparent 39%,var(--sk-edge) 40%,var(--sk-highlight) 43%,transparent 44%,transparent 53%,var(--sk-edge) 54%,var(--sk-highlight) 57%,transparent 58%),linear-gradient(135deg,var(--sk-surface-raised),var(--sk-base)); box-shadow: inset 0 2px 0 var(--sk-highlight),inset 0 -2px 0 var(--sk-base),0 3px 0 var(--sk-edge),0 5px 7px var(--sk-shadow); }
.sk-slider-housing input[type="range"]::-moz-range-thumb{ width: 26px; height: 34px; border-radius: 6px; border: 1px solid var(--sk-key-edge); background: linear-gradient(to bottom,transparent 39%,var(--sk-edge) 40%,var(--sk-highlight) 43%,transparent 44%,transparent 53%,var(--sk-edge) 54%,var(--sk-highlight) 57%,transparent 58%),linear-gradient(135deg,var(--sk-surface-raised),var(--sk-base)); box-shadow: inset 0 2px 0 var(--sk-highlight),0 3px 0 var(--sk-edge),0 5px 7px var(--sk-shadow); }
.sk-slider-ticks{ display: flex; align-items: flex-end; justify-content: space-between; position: absolute; left: 19px; right: 19px; bottom: 5px; height: 6px; }
.sk-slider-ticks i{ width: 1px; height: 3px; background: var(--sk-edge); }
.sk-slider-ticks i:nth-child(5n + 1){ height: 6px; }
.sk-slider-housing[data-disabled]{ opacity: .5; }
.sk-slider-housing input:disabled{ cursor: not-allowed; }
.sk-slider-housing{ width:100%;height:68px;padding-inline:18px;border-radius:11px;background:linear-gradient(150deg,var(--sk-surface-raised),var(--sk-base));box-shadow:inset 0 2px 0 var(--sk-highlight),inset 2px 0 2px var(--sk-highlight),inset 0 -3px 0 var(--sk-base),0 5px 0 var(--sk-base),0 6px 0 var(--sk-edge),0 12px 15px var(--sk-shadow); }
.sk-slider-housing::before{content:"";position:absolute;inset:7px 8px 19px;border:1px solid var(--sk-edge);border-radius:6px;background:var(--sk-well);box-shadow:inset 0 5px 8px var(--sk-shadow),inset 2px 1px 3px var(--sk-shadow),0 1px 0 var(--sk-highlight);pointer-events:none;}
.sk-slider-housing .sk-slider-track{top:25px;left:20px;right:20px;height:8px;border-color:var(--sk-key-edge);box-shadow:inset 0 3px 4px #00000070,0 1px var(--sk-highlight);}
.sk-slider-housing input[type="range"]{height:54px;appearance:none;cursor:grab;}
.sk-slider-housing input[type="range"]:active{cursor:grabbing;}
.sk-slider-housing input[type="range"]::-webkit-slider-thumb{appearance:none;width:23px;height:29px;border:1px solid var(--sk-key-edge);border-radius:5px;background:repeating-linear-gradient(90deg,transparent 0 4px,var(--sk-edge) 4px 5px,var(--sk-highlight) 5px 6px,transparent 6px 8px),linear-gradient(135deg,var(--sk-surface-raised),var(--sk-base));box-shadow:inset 0 2px var(--sk-highlight),inset 0 -3px var(--sk-base),0 4px var(--sk-key-base),0 5px var(--sk-key-edge),0 8px 7px #00000060;}
.sk-slider-housing input[type="range"]::-moz-range-thumb{width:23px;height:29px;border:1px solid var(--sk-key-edge);border-radius:5px;background:repeating-linear-gradient(90deg,transparent 0 4px,var(--sk-edge) 4px 5px,var(--sk-highlight) 5px 6px,transparent 6px 8px),linear-gradient(135deg,var(--sk-surface-raised),var(--sk-base));box-shadow:inset 0 2px var(--sk-highlight),0 4px var(--sk-key-base),0 5px var(--sk-key-edge),0 8px 7px #00000060;}
.sk-slider-housing .sk-slider-ticks{bottom:6px;left:22px;right:22px;height:7px;}
.sk-slider-housing input:focus-visible{outline:2px solid var(--sk-ring);outline-offset:7px;border-radius:4px;}

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root]:focus-visible,[data-sk-root] :focus-visible) {outline:2px solid var(--sk-ring);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Exact material defaults, with optional host semantic colors. Public host tokens are never written. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper: var(--card, #faf9f5);--sk-album-ink: var(--card-foreground, #45423b);--sk-album-edge: var(--border, #c4c2ba);--sk-album-base: var(--sk-sem-album-base, #d6d4ca);
  --sk-bg: var(--background, #fff); --sk-ink: var(--foreground, #202020); --sk-muted: var(--muted-foreground, #777774); --sk-line: var(--border, #e7e7e4);
  --sk-surface: var(--card, #f5f5f2); --sk-surface-raised: var(--sk-sem-surface-raised, #fafaf8); --sk-well: var(--muted, #e9e9e5);
  --sk-edge: var(--border, #d1d1cb); --sk-highlight: #fff; --sk-base: var(--sk-sem-base, #d9d9d3); --sk-shadow: #00000017;
  --sk-field-shadow: inset 0 3px 6px var(--sk-shadow),inset 1px 1px 2px var(--sk-shadow),0 1px 0 var(--sk-highlight);
  --sk-accent: var(--primary, #365e50); --sk-accent-bright: var(--sk-sem-accent-bright, #487b68); --sk-accent-base: var(--sk-sem-accent-base, #213c32); --sk-accent-edge: var(--sk-sem-accent-edge, #294b3e); --sk-accent-ink: var(--primary-foreground, #fff);
  --sk-key: var(--secondary, #f9f9f7); --sk-key-edge: var(--border, #c6c7c1); --sk-key-base: var(--sk-sem-key-base, #d0d1ca);
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

} }

:where(:root,.light,.dark,[data-theme="light"],[data-theme="dark"]) {
  --sk-sem-accent-bright: color-mix(in srgb,var(--primary) 84%,white);
  --sk-sem-accent-base: color-mix(in srgb,var(--primary) 65%,black);
  --sk-sem-accent-edge: color-mix(in srgb,var(--primary) 78%,black);
  --sk-sem-base: color-mix(in srgb,var(--card) 85%,black);
  --sk-sem-surface-raised: color-mix(in srgb,var(--card) 96%,white);
  --sk-sem-key-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-sem-album-base: color-mix(in srgb,var(--card) 83%,black);
  --sk-card-ink: var(--card-foreground,var(--sk-ink));
  --sk-sem-secondary-raised: color-mix(in srgb,var(--secondary) 96%,white);
  --sk-sem-secondary-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-secondary: var(--secondary,var(--sk-surface));
  --sk-secondary-ink: var(--secondary-foreground,var(--sk-ink));
  --sk-secondary-raised: var(--sk-sem-secondary-raised,var(--sk-surface-raised));
  --sk-secondary-base: var(--sk-sem-secondary-base,var(--sk-base));
  --sk-input-edge: var(--input,var(--sk-edge));
  --sk-ring: var(--ring,var(--sk-accent));
}
